"""L4 -- build something that uses the detector.

One contract, three reasonable things to build with it. Pick one:

  blur       obscure every detected face; the privacy tool
  count      draw the boxes and stamp the count; the attendance counter
  overlay    draw something on each face; the AR toy

The grader does not care which you chose. It checks that a real image came
back, that it differs from the one that went in, that the differences are
concentrated in and around the face boxes rather than smeared over the whole
frame, and that the report carries the required keys. Those are true of all
three, which is the point -- the level grades whether your app works, not
whether the instructor liked your idea.

This is the open-ended level. Its output is the artifact you keep, and taste
is not graded.
"""

from __future__ import annotations

import numpy as np

# The mode this team built. "overlay" draws an outline and a small numbered tag
# on each box the caller supplies, so a viewer can see exactly where the
# detector put boxes. The number is detection order within one frame, nothing
# more: no identity, no score, no tracking between frames.
MODES = ("overlay",)

_OUTLINE = np.array([0, 255, 255], dtype=np.uint8)   # cyan
_TAG_BG = (0, 0, 0)
_TAG_FG = (0, 255, 255)


def process(image, faces, mode="overlay"):
    """Apply `mode` to every face in `image` and describe what happened.

    image  : an (H, W, 3) uint8 RGB array
    faces  : list of (x1, y1, x2, y2) integer boxes, as `detect_faces` returns
    mode   : "blur", "count" or "overlay"

    Returns (annotated, report) where:
      annotated : a NEW (H, W, 3) uint8 array. Do not modify `image` in place;
                  the grader compares the two.
      report    : a dict with at least these keys
                    "n_faces"      int, how many boxes were acted on
                    "mode"         str, the mode applied
                    "coverage"     float in [0, 1], the fraction of the frame
                                   area inside face boxes

    An image with no faces still returns a valid pair: a copy of the input and
    a report with n_faces 0.

    Boxes can run past the edge of the frame. Clip them before you index.

    This app implements "overlay" only (the default). The boxes are drawn
    exactly as given; `process` never runs a detector itself.
    """
    if mode not in MODES:
        raise ValueError(f"mode {mode!r} is not implemented; this app builds {MODES}")

    src = np.asarray(image)
    if src.ndim != 3 or src.shape[2] != 3:
        raise ValueError(f"image must be (H, W, 3), got shape {src.shape}")
    # A new array: the input is often read-only (straight from a file) and the
    # caller still needs the original.
    out = np.array(src, dtype=np.uint8, copy=True)
    h, w = out.shape[:2]

    acted = []
    covered = np.zeros((h, w), dtype=bool)
    for box in faces:
        clipped = _clip_box(box, w, h)
        if clipped is None:          # entirely off-frame: nothing to act on
            continue
        acted.append(clipped)
        x1, y1, x2, y2 = clipped
        covered[y1:y2, x1:x2] = True

    for number, box in enumerate(acted, start=1):
        _draw_outline(out, box)
        _draw_tag(out, box, f"face {number}")

    report = {
        "n_faces": len(acted),
        "mode": mode,
        "coverage": float(covered.sum()) / float(h * w) if h * w else 0.0,
        "boxes": acted,
    }
    return out, report


def _clip_box(box, w, h):
    """Round and clip (x1, y1, x2, y2) to the frame; None if nothing is left."""
    x1, y1, x2, y2 = (int(round(float(v))) for v in box)
    x1, x2 = max(0, min(x1, w)), max(0, min(x2, w))
    y1, y2 = max(0, min(y1, h)), max(0, min(y2, h))
    if x2 <= x1 or y2 <= y1:
        return None
    return (x1, y1, x2, y2)


def _draw_outline(out, box):
    """Rectangle drawn on the inside edge of the box, so nothing spills outside."""
    x1, y1, x2, y2 = box
    t = max(2, min(x2 - x1, y2 - y1) // 50)
    t = min(t, (x2 - x1 + 1) // 2, (y2 - y1 + 1) // 2)
    out[y1:y1 + t, x1:x2] = _OUTLINE
    out[y2 - t:y2, x1:x2] = _OUTLINE
    out[y1:y2, x1:x1 + t] = _OUTLINE
    out[y1:y2, x2 - t:x2] = _OUTLINE


def _draw_tag(out, box, text):
    """Small label in the box's top-left corner; skipped if it does not fit."""
    from PIL import Image, ImageDraw, ImageFont

    x1, y1, x2, y2 = box
    bw, bh = x2 - x1, y2 - y1
    size = max(10, min(bw, bh) // 9)
    try:
        font = ImageFont.load_default(size=size)
    except TypeError:                # very old Pillow: fixed-size bitmap font
        font = ImageFont.load_default()
    pad = max(2, size // 5)
    inset = max(2, min(bw, bh) // 50) + 1
    left, top, right, bottom = font.getbbox(text)
    tw, th = right - left + 2 * pad, bottom - top + 2 * pad
    if tw > bw - 2 * inset or th > bh - 2 * inset:
        return

    tag = Image.new("RGB", (tw, th), _TAG_BG)
    ImageDraw.Draw(tag).text((pad - left, pad - top), text, font=font, fill=_TAG_FG)
    tx, ty = x1 + inset, y1 + inset
    out[ty:ty + th, tx:tx + tw] = np.asarray(tag, dtype=np.uint8)
